<template>
  <CModal :show="show" size="xl" centered class="admin-modal" @update:show="$emit('update:show', $event)">
    <template #header><div class="d-flex justify-content-between align-items-center w-100"><div><h5 class="mb-1">นำเข้าผลงานเข้า Submission</h5><small class="text-muted">อัปโหลด Excel และรูปภาพหลายไฟล์ แล้วตรวจสอบก่อนบันทึก</small></div><button class="close-btn" @click="$emit('update:show', false)"><CIcon name="cil-x"/></button></div></template>
    <div class="p-3">
      <div class="row">
        <div class="col-md-6"><label>Submission *</label><select v-model="submissionId" class="form-control"><option value="">เลือก Submission</option><option v-for="s in submissions" :key="s._id" :value="s._id">{{ name(s.title) }}</option></select></div>
        <div class="col-md-6"><label>หัวข้องาน *</label><select v-model="assignmentId" class="form-control" :disabled="!selectedSubmission"><option value="">เลือกหัวข้องาน</option><option v-for="a in assignments" :key="a._id" :value="a._id">{{ name(a.title) }}</option></select></div>
      </div>
      <div class="row mt-3"><div class="col-md-6"><label>ไฟล์ Excel *</label><input ref="excel" type="file" accept=".xlsx,.xls,.csv" class="form-control" @change="readExcel"></div><div class="col-md-6"><label>รูปภาพผลงาน *</label><input ref="images" type="file" accept="image/*" multiple class="form-control" @change="setImages"><small class="text-muted">ตั้งชื่อไฟล์ให้ตรงกับชื่อผลงาน หรือระบุชื่อไฟล์ในคอลัมน์ ImageFilename</small></div></div>
      <div v-if="error" class="alert alert-danger mt-3 mb-0">{{ error }}</div>
      <div v-if="rows.length" class="mt-4"><div class="d-flex justify-content-between align-items-center"><h6>ตัวอย่างข้อมูล ({{ rows.length }} รายการ)</h6><span :class="validCount === rows.length ? 'text-success' : 'text-warning'">จับคู่รูปได้ {{ validCount }}/{{ rows.length }}</span></div><div class="table-responsive preview"><table class="table table-sm"><thead><tr><th>ชื่อผลงาน</th><th>ผู้เรียน</th><th>หมวดหมู่</th><th>รูปภาพ</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td>{{ r.titleTh || r.titleEn || '-' }}</td><td>{{ r.artist || '-' }} <span v-if="!r.artistId" class="text-danger">ไม่พบ</span></td><td>{{ r.category || '-' }}</td><td><span :class="r.image ? 'text-success' : 'text-danger'">{{ r.image ? r.image.name : 'ไม่พบรูป' }}</span></td></tr></tbody></table></div></div>
    </div>
    <template #footer><div class="w-100 d-flex justify-content-between"><button class="btn btn-link" @click="$emit('update:show', false)">ยกเลิก</button><div><button class="btn btn-outline-secondary mr-2" @click="downloadTemplate">ดาวน์โหลด Template</button><button class="btn btn-primary" :disabled="!canImport || busy" @click="importRows">{{ busy ? 'กำลังนำเข้า...' : 'นำเข้าและบันทึก' }}</button></div></div></template>
  </CModal>
</template>
<script>
import * as XLSX from 'xlsx'
export default {
  name:'ArtworkImportModal', props:{show:Boolean, submissions:{type:Array,default:()=>[]}},
  data(){return {submissionId:'',assignmentId:'',rows:[],images:[],error:'',busy:false,categories:[]}},
  computed:{selectedSubmission(){return this.submissions.find(s=>s._id===this.submissionId)}, assignments(){return this.selectedSubmission?.assignments||[]},validCount(){return this.rows.filter(r=>r.image&&r.artistId).length},canImport(){return !!this.selectedSubmission&&!!this.assignmentId&&this.rows.length>0&&this.validCount===this.rows.length}},
  watch:{show(v){if(v){this.error='';this.rows=[];this.images=[];this.assignmentId='';this.loadCategories()}}},
  methods:{
    name(v){if(!v)return '-';if(typeof v==='string')return v;return (v.find?.(x=>x.key===this.$i18n.locale)||v[0])?.value||'-'}, norm(v){return String(v||'').toLowerCase().trim().replace(/\.[^.]+$/,'').replace(/[\s_\-()]+/g,'')}, field(row,names){const keys=Object.keys(row);const k=keys.find(x=>names.some(n=>this.norm(x)===this.norm(n)));return k?row[k]:''},
    async loadCategories(){try{this.categories=await this.$store.dispatch('artwork/category',{method:'get'})||[]}catch(e){this.categories=[]}}, category(v){const q=this.norm(v);const c=this.categories.find(x=>this.norm(this.name(x.name||x.title))===q||this.norm(x.nameEn)===q||this.norm(x.nameTh)===q);return c?c._id:null},
    setImages(e){this.images=Array.from(e.target.files||[]);this.rematch()},
    async readExcel(e){const f=e.target.files?.[0];if(!f)return;try{const wb=XLSX.read(await f.arrayBuffer(),{type:'array'});const raw=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});const users=this.$store.getters['user/user']||[];this.rows=raw.map((x,i)=>{const artist=String(this.field(x,['ArtistID','StudentID'])).trim();const u=users.find(a=>String(a.studentId||a.studentID||'')===artist);return {raw:x,titleTh:String(this.field(x,['ArtworkTitleThai','TitleThai'])).trim(),titleEn:String(this.field(x,['ArtworkTitleEng','ArtworkTitleEnglish','TitleEng'])).trim(),descriptionTh:this.field(x,['DescriptionThai']),descriptionEn:this.field(x,['DescriptionEng']),techniqueTh:this.field(x,['TechniqueThai']),techniqueEn:this.field(x,['TechniqueEng']),sizeTh:this.field(x,['SizeThai']),sizeEn:this.field(x,['SizeEng']),remarkTh:this.field(x,['RemarkThai']),remarkEn:this.field(x,['RemarkEng']),price:Number(String(this.field(x,['Price'])).replace(/,/g,''))||0,artist,artistId:u?u._id:null,category:String(this.field(x,['Category'])).trim(),categoryId:this.category(this.field(x,['Category']))}});this.rematch()}catch(err){this.error='อ่านไฟล์ Excel ไม่สำเร็จ'}},
    rematch(){this.rows=this.rows.map((r,i)=>{const explicit=this.field(r.raw,['ImageFilename','Image','ArtworkImage','Filename','__EMPTY']);const candidates=[explicit,r.titleTh,r.titleEn].filter(Boolean).map(this.norm);let img=this.images.find(f=>candidates.includes(this.norm(f.name)));if(!img)this.images.forEach((f,j)=>{if(!img&&j===i)img=f});return {...r,image:img}})}, bilingual(th,en){const a=[];if(th)a.push({key:'th',value:String(th)});if(en)a.push({key:'en',value:String(en)});return a},
    async importRows(){this.busy=true;this.error='';try{const sub=JSON.parse(JSON.stringify(this.selectedSubmission));const asg=sub.assignments.find(a=>a._id===this.assignmentId);if(!asg)throw Error('Assignment not found');asg.artworks=asg.artworks||[];asg.artist=asg.artist||[];sub.artist=sub.artist||[];const status=(this.$store.getters['setting/status/item']||[]).find(s=>this.name(s.title||s.name).toLowerCase().includes('pending')||this.name(s.title||s.name).includes('รอตรวจ'))?._id;for(const r of this.rows){const fd=new FormData();fd.append('_id',sub._id);fd.append('assignmentTitle',this.name(asg.title));fd.append('artworkTitle',r.titleTh||r.titleEn);fd.append('image',r.image);const up=await this.$store.dispatch('submission/upload',fd);const aw={title:this.bilingual(r.titleTh,r.titleEn),description:this.bilingual(r.descriptionTh,r.descriptionEn),technique:this.bilingual(r.techniqueTh,r.techniqueEn),size:this.bilingual(r.sizeTh,r.sizeEn),remark:this.bilingual(r.remarkTh,r.remarkEn),price:r.price,image:up.data?.data?.url||up.data?.url,owner:r.artistId,category:r.categoryId||null,status:status||null,create:{at:new Date()}};asg.artworks.push(aw);if(!asg.artist.includes(r.artistId))asg.artist.push(r.artistId);if(!sub.artist.includes(r.artistId))sub.artist.push(r.artistId)}await this.$store.dispatch('submission/update',{_id:sub._id,artist:sub.artist,assignments:sub.assignments});this.$emit('imported',this.rows.length);this.$emit('update:show',false)}catch(e){console.error(e);this.error='นำเข้าไม่สำเร็จ กรุณาตรวจสอบข้อมูล ผู้เรียน และรูปภาพ'}finally{this.busy=false}},
    downloadTemplate(){const ws=XLSX.utils.aoa_to_sheet([['ArtworkTitleThai','ArtworkTitleEng','DescriptionThai','DescriptionEng','TechniqueThai','TechniqueEng','SizeThai','SizeEng','Price','ArtistID','Category','SaleStatus','ShowStatuses','RemarkThai','RemarkEng','ImageFilename']]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Artwork_Template');XLSX.writeFile(wb,'Artwork_Import_Template.xlsx')}
  }
}
</script>
<style scoped>.preview{max-height:260px}.close-btn{border:0;background:none;color:#8792a2}label{font-weight:600}.btn-primary{background:#7b3f32;border-color:#7b3f32}</style>
